using ContosoUniversity.Services;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue before each test to avoid cross-test interference
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "TestUser");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _sut.SendNotification("Department", "5", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithExplicitUserName_SetsCreatedBy()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "Jane", EntityOperation.CREATE, "AdminUser");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("AdminUser", notification.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            // Arrange & Act
            _sut.SendNotification("Instructor", "7", "Dr. Smith", operation, "User");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(expectedVerb, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToApproximatelyNow()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-1);

            // Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            var after = DateTime.Now.AddSeconds(1);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleSends_ReturnsFifoOrder()
        {
            // Arrange
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            // Act & Assert
            var first = _sut.ReceiveNotification();
            Assert.NotNull(first);
            Assert.Equal("A", first.EntityType);

            var second = _sut.ReceiveNotification();
            Assert.NotNull(second);
            Assert.Equal("B", second.EntityType);

            var third = _sut.ReceiveNotification();
            Assert.NotNull(third);
            Assert.Equal("C", third.EntityType);

            var fourth = _sut.ReceiveNotification();
            Assert.Null(fourth);
        }

        [Fact]
        public void SendNotification_WithWhitespaceDisplayName_UsesEntityIdFallback()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "99", "   ", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 99", notification.Message);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesEntityIdFallback()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "99", "", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 99", notification.Message);
        }

        [Fact]
        public void SendNotification_WithDisplayName_IncludesNameInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Department", "3", "Engineering", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Engineering", notification.Message);
            Assert.DoesNotContain("ID:", notification.Message);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert (no-op for in-memory, just verify no exception)
            var exception = Record.Exception(() => _sut.MarkAsRead(42));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_SetsIsReadFalse()
        {
            // Act
            _sut.SendNotification("Course", "1", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Act & Assert
            var sut = new NotificationService();
            var exception = Record.Exception(() =>
            {
                sut.Dispose();
                sut.Dispose();
            });
            Assert.Null(exception);
        }
    }
}

