using Xunit;
using System.Collections.Generic;
using System.Linq;

namespace ContosoUniversity.Tests.Helpers
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndexAndTotalPages()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        [Theory]
        [InlineData(10, 3, 4)]   // ceil(10/3) = 4
        [InlineData(10, 5, 2)]   // ceil(10/5) = 2
        [InlineData(10, 10, 1)]  // ceil(10/10) = 1
        [InlineData(0, 5, 0)]    // ceil(0/5) = 0
        [InlineData(1, 5, 1)]    // ceil(1/5) = 1
        [InlineData(11, 5, 3)]   // ceil(11/5) = 3
        public void Constructor_CalculatesTotalPagesCorrectly(int totalCount, int pageSize, int expectedTotalPages)
        {
            // Arrange
            var items = new List<int>();

            // Act
            var list = new PaginatedList<int>(items, totalCount, 1, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, list.TotalPages);
        }

        [Theory]
        [InlineData(1, false)]   // First page — no previous
        [InlineData(2, true)]    // Second page — has previous
        [InlineData(3, true)]    // Third page — has previous
        public void HasPreviousPage_ReturnsCorrectValue(int pageIndex, bool expected)
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 30, pageIndex, 10);

            // Act & Assert
            Assert.Equal(expected, list.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, 3, true)]   // Page 1 of 3 — has next
