using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander"
            };

            // Act
            var fullName = student.FullName;

            // Assert
            Assert.Equal("Alexander, Carson", fullName);
        }

        [Fact]
        public void FullName_WithInstructor_ReturnsCorrectFormat()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie"
            };

            // Act & Assert
            Assert.Equal("Abercrombie, Kim", instructor.FullName);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_WhenRequestIdIsSet_ReturnsTrue()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = "abc123" };

            // Act & Assert
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_WhenRequestIdIsNull_ReturnsFalse()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = null };

            // Act & Assert
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_WhenRequestIdIsEmpty_ReturnsFalse()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = "" };

            // Act & Assert
            Assert.False(model.ShowRequestId);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_DefaultProperties_AreSetCorrectly()
        {
            // Arrange & Act
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };

            // Assert
            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Null(course.TeachingMaterialImagePath);
        }
    }

    public class DepartmentTests
    {
        [Fact]
        public void Department_Properties_AreSetCorrectly()
        {
            // Arrange
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new System.DateTime(2007, 9, 1),
                InstructorID = 5
            };

            // Assert
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(new System.DateTime(2007, 9, 1), dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_CanBeNull()
        {
            // Arrange
            var dept = new Department { Name = "Unassigned" };

            // Assert
            Assert.Null(dept.InstructorID);
        }
    }

    public class EnrollmentTests
    {
        [Fact]
        public void Enrollment_Grade_CanBeNull()
        {
            // Arrange
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 10
            };

            // Assert
            Assert.Null(enrollment.Grade);
        }

