        [InlineData(Grade.A)]
        [InlineData(Grade.B)]
        [InlineData(Grade.C)]
        [InlineData(Grade.D)]
        [InlineData(Grade.F)]
        public void Enrollment_Grade_CanBeSetToAnyValue(Grade grade)
        {
            // Arrange
            var enrollment = new Enrollment { Grade = grade };

            // Assert
            Assert.Equal(grade, enrollment.Grade);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_DefaultIsRead_IsFalse()
        {
            // Arrange & Act
            var notification = new Notification();

            // Assert
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void Notification_Properties_AreSetCorrectly()
        {
            // Arrange
            var createdAt = new System.DateTime(2024, 1, 15, 10, 30, 0);
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "New Student created",
                CreatedAt = createdAt,
                CreatedBy = "Admin",
                IsRead = true,
                ReadAt = createdAt.AddMinutes(5)
            };

            // Assert
            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student created", notification.Message);
            Assert.Equal(createdAt, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.True(notification.IsRead);
            Assert.Equal(createdAt.AddMinutes(5), notification.ReadAt);
        }

        [Fact]
        public void Notification_ReadAt_CanBeNull()
        {
            // Arrange
            var notification = new Notification();

            // Assert
            Assert.Null(notification.ReadAt);
        }
    }

    public class EntityOperationEnumTests
    {
        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }
    }

    public class CourseAssignmentTests
    {
        [Fact]
        public void CourseAssignment_Properties_AreSetCorrectly()
        {
