                CourseID = 1050
            };

            // Assert
            Assert.Equal(5, ca.InstructorID);
            Assert.Equal(1050, ca.CourseID);
        }
    }

    public class OfficeAssignmentTests
    {
        [Fact]
        public void OfficeAssignment_Properties_AreSetCorrectly()
        {
            // Arrange & Act
            var oa = new OfficeAssignment
            {
                InstructorID = 3,
                Location = "Thompson 304"
            };

            // Assert
            Assert.Equal(3, oa.InstructorID);
            Assert.Equal("Thompson 304", oa.Location);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void Student_InheritsFromPerson()
        {
            // Arrange & Act
            var student = new Student
            {
                ID = 1,
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new System.DateTime(2024, 1, 1)
            };

            // Assert — confirms inheritance chain
            Assert.IsAssignableFrom<Person>(student);
            Assert.Equal("User, Test", student.FullName);
            Assert.Equal(new System.DateTime(2024, 1, 1), student.EnrollmentDate);
        }
    }

    public class InstructorTests
    {
        [Fact]
        public void Instructor_InheritsFromPerson()
        {
            // Arrange & Act
            var instructor = new Instructor
            {
                ID = 1,
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = new System.DateTime(2000, 5, 15)
            };

