using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new StudentsController(_context);
            // Set up TempData for the controller
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock_ITempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        // --- Index ---

        [Fact]
        public void Index_NoParameters_ReturnsViewWithStudents()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count); // 3 seeded students
        }

        [Fact]
        public void Index_SortByNameDescending_ReturnsDescendingOrder()
        {
            // Act
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.True(model.Count > 0);
            // Verify descending order: first student should have alphabetically later last name
            for (int i = 0; i < model.Count - 1; i++)
            {
                Assert.True(string.Compare(model[i].LastName, model[i + 1].LastName, StringComparison.Ordinal) >= 0,
                    $"Expected '{model[i].LastName}' >= '{model[i + 1].LastName}' for descending sort");
            }
        }

        [Fact]
        public void Index_SortByDateAscending_ReturnsDateOrder()
        {
            // Act
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            for (int i = 0; i < model.Count - 1; i++)
            {
                Assert.True(model[i].EnrollmentDate <= model[i + 1].EnrollmentDate);
            }
        }

        [Fact]
        public void Index_SortByDateDescending_ReturnsReverseDateOrder()
        {
            // Act
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            for (int i = 0; i < model.Count - 1; i++)
            {
                Assert.True(model[i].EnrollmentDate >= model[i + 1].EnrollmentDate);
            }
        }

        [Fact]
        public void Index_DefaultSort_ReturnsLastNameAscending()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            for (int i = 0; i < model.Count - 1; i++)
            {
                Assert.True(string.Compare(model[i].LastName, model[i + 1].LastName, StringComparison.Ordinal) <= 0);
            }
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            // Act
            var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            // Act
            var result = _controller.Index(null, null, "Meredith", null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Meredith", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchNoMatch_ReturnsEmptyList()
        {
            // Act
            var result = _controller.Index(null, null, "NonexistentXYZ", null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageTo1()
        {
            // When searchString is provided (not null), page should be set to 1
            // Act
            var result = _controller.Index(null, null, "A", 5) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            // When searchString is null, it uses currentFilter
            // Act
            var result = _controller.Index(null, "Alexander", null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
        }

        [Fact]
        public void Index_SetsViewBagSortParameters()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_WithDateSortOrder_SetsDateSortParmToDateDesc()
        {
            // Act
            _controller.Index("Date", null, null, null);

            // Assert
            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            // Act
            var result = _controller.Details(10) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alexander", student.LastName);
            Assert.Equal("Carson", student.FirstMidName);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, student.EnrollmentDate);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = new DateTime(2024, 1, 15)
            };

            // Act
            var result = _controller.Create(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            // Verify student was actually saved
            Assert.Equal(4, _context.Students.Count());
            var saved = _context.Students.First(s => s.LastName == "Student");
            Assert.Equal("New", saved.FirstMidName);
            Assert.Equal(new DateTime(2024, 1, 15), saved.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_DefaultEnrollmentDate_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = DateTime.MinValue
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_DateBeforeSqlMinimum_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = new DateTime(1752, 12, 31)
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2024, 1, 1)
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(3, _context.Students.Count()); // No new student added
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            // Act
            var result = _controller.Edit((int?)10) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alexander", student.LastName);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit((int?)99999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            // Arrange — use a detached entity to simulate form-submitted data
            var student = new Student
            {
                ID = 10,
                FirstMidName = "UpdatedCarson",
                LastName = "Alexander",
                EnrollmentDate = new DateTime(2010, 9, 1)
            };
            // Detach tracked entity first
            var tracked = _context.Students.Find(10);
            _context.Entry(tracked!).State = EntityState.Detached;

            // Act
            var result = _controller.Edit(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_DefaultEnrollmentDate_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                ID = 10,
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = default
            };

            // Act
            var result = _controller.Edit(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
