using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new DepartmentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithDepartment()
        {
            // Act
            var result = _controller.Details(1) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var dept = Assert.IsType<Department>(result.Model);
            Assert.Equal("English", dept.Name);
            Assert.Equal(350000m, dept.Budget);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Details(99999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsView()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidDepartment_RedirectsToIndex()
        {
            // Arrange
            var department = new Department
            {
                Name = "Science",
                Budget = 200000m,
                StartDate = new DateTime(2024, 1, 1),
                InstructorID = 1
            };

            // Act
            var result = _controller.Create(department);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            // Verify saved
            Assert.Equal(3, _context.Departments.Count());
            var saved = _context.Departments.First(d => d.Name == "Science");
            Assert.Equal(200000m, saved.Budget);
            Assert.Equal(1, saved.InstructorID);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("Name", "Required");
            var department = new Department { Budget = 100000 };

            // Act
            var result = _controller.Create(department) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(2, _context.Departments.Count()); // No new department
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithDepartment()
        {
            // Act
            var result = _controller.Edit((int?)1) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var dept = Assert.IsType<Department>(result.Model);
            Assert.Equal("English", dept.Name);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit((int?)99999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidDepartment_RedirectsToIndex()
        {
            // Arrange
            var department = new Department
            {
                DepartmentID = 1,
                Name = "Updated English",
                Budget = 400000m,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 1
            };
            // Detach tracked entity
            var tracked = _context.Departments.Find(1);
            _context.Entry(tracked!).State = EntityState.Detached;

            // Act
            var result = _controller.Edit(department);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("Name", "Required");
            var department = new Department
            {
                DepartmentID = 1,
                Name = "English",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1)
            };

            // Act
            var result = _controller.Edit(department) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithDepartment()
        {
            // Act
            var result = _controller.Delete(1) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var dept = Assert.IsType<Department>(result.Model);
            Assert.Equal("English", dept.Name);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Delete(99999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        // --- DeleteConfirmed ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
        {
            // Act
            var result = _controller.DeleteConfirmed(1);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Departments);
            Assert.Null(_context.Departments.Find(1));
        }
    }
}

