namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentDateGroups()
        {
            // Act
            var result = _controller.About() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
            Assert.True(model.Count > 0);

            // Verify the groups have correct counts — our seed data has 3 students with
            // different enrollment dates, so we should have distinct groups
            var totalStudents = model.Sum(g => g.StudentCount);
            Assert.Equal(3, totalStudents); // 3 seeded students
        }

        [Fact]
        public void About_GroupsByEnrollmentDate()
        {
            // Act
            var result = _controller.About() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);

            // Our seed data: Alexander=2010-09-01, Alonso=2012-09-01, Anand=2013-09-01
            // All different dates, so we should have 3 groups
            Assert.Equal(3, model.Count);
            Assert.All(model, g =>
            {
                Assert.Equal(1, g.StudentCount);
                Assert.NotNull(g.EnrollmentDate);
            });
        }

        [Fact]
        public void Contact_ReturnsViewWithMessage()
        {
            // Act
            var result = _controller.Contact() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsViewResult()
        {
            // Act
            var result = _controller.Error();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewWithMessage()
        {
            // Act
            var result = _controller.Unauthorized() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
        }
    }
}

