using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_WhenNoNotifications_ReturnsSuccessWithEmptyList()
        {
            // Drain any stale notifications from static queue
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);

            // Verify the anonymous object shape by checking its dynamic properties
            var value = jsonResult.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);

            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            Assert.Equal(0, (int)countProp.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_WithQueuedNotifications_ReturnsNotifications()
        {
            // Arrange — drain the static queue first
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }

            // Now enqueue some notifications
            service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "User");
            service.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "User");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value!;

            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);

            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(2, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.NotNull(result);
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value!;

            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_ReturnsSuccess()
        {
            // The in-memory implementation is a no-op, but should still return success
            // Act
            var result = _controller.MarkAsRead(99999);

            // Assert
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }
    }
}

