using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.IO;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional controller tests to increase coverage on edge cases and
    /// code paths not exercised by the primary test classes.
    /// </summary>
    public class CoursesControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly string _tempDir;

        public CoursesControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _envMock = new Mock<IWebHostEnvironment>();
            var loggerMock = new Mock<ILogger<CoursesController>>();

            _tempDir = Path.Combine(Path.GetTempPath(), "ContosoEdge_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempDir);
            _envMock.Setup(e => e.WebRootPath).Returns(_tempDir);
            _envMock.Setup(e => e.ContentRootPath).Returns(_tempDir);

            _controller = new CoursesController(_context, _envMock.Object, loggerMock.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { Directory.Delete(_tempDir, true); } catch { }
        }

        [Fact]
        public void Edit_Post_WithValidImage_SavesNewImageAndRedirects()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };
            var tracked = _context.Courses.Find(1050);
            _context.Entry(tracked!).State = EntityState.Detached;

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("newimage.png");
            fileMock.Setup(f => f.Length).Returns(2048);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            // Act
            var result = _controller.Edit(course, fileMock.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_WithExistingImage_ReplacesOldImage()
        {
            // Arrange — set up a course with an existing image path
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old.jpg"
            };
            var tracked = _context.Courses.Find(1050);
            _context.Entry(tracked!).State = EntityState.Detached;

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("replacement.jpg");
            fileMock.Setup(f => f.Length).Returns(2048);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            // Act
            var result = _controller.Edit(course, fileMock.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImage_DeletesImageFile()
        {
            // Arrange — create a real image file
            var uploadsDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsDir);
            var imageFile = Path.Combine(uploadsDir, "test_image.jpg");
            File.WriteAllText(imageFile, "fake image data");

            // Set the course's image path
            var course = _context.Courses.Find(1050);
            course!.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test_image.jpg";
            _context.SaveChanges();

            // Act
            _controller.DeleteConfirmed(1050);

            // Assert
            Assert.False(File.Exists(imageFile));
        }

        [Fact]
        public void DeleteConfirmed_CourseWithNoImage_StillSucceeds()
        {
            // Arrange — course has no image path (null)
            var course = _context.Courses.Find(1050);
            Assert.Null(course!.TeachingMaterialImagePath); // Default is null

            // Act
            var result = _controller.DeleteConfirmed(1050);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_WebRootPathNull_UsesContentRootPath()
        {
            // Arrange — WebRootPath is null
            _envMock.Setup(e => e.WebRootPath).Returns((string)null!);

            var course = new Course
            {
                CourseID = 3333,
                Title = "Art History",
                Credits = 2,
                DepartmentID = 1
            };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("art.jpg");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            // Act
            var result = _controller.Create(course, fileMock.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }
    }

    public class StudentsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new StudentsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock_ITempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Create_Post_ValidDate_AtSqlMinBoundary_Succeeds()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Boundary",
                LastName = "Min",
                EnrollmentDate = new DateTime(1753, 1, 1) // Exact SQL min boundary
            };

            // Act
            var result = _controller.Create(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_ValidDateUpdate_SavesAndRedirects()
        {
            // Arrange
            var student = new Student
            {
                ID = 11,
                FirstMidName = "Meredith",
                LastName = "AlonsoUpdated",
                EnrollmentDate = new DateTime(2020, 6, 15)
            };
            var tracked = _context.Students.Find(11);
            _context.Entry(tracked!).State = EntityState.Detached;

            // Act
            var result = _controller.Edit(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_DateBeforeSqlMinimum_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                ID = 10,
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = new DateTime(1700, 1, 1)
            };

            // Act
            var result = _controller.Edit(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Index_PaginationWorks_WithManyStudents()
        {
            // Arrange — add enough students to need pagination
            for (int i = 100; i < 120; i++)
            {
                _context.Students.Add(new Student
                {
                    ID = i,
                    FirstMidName = $"First{i}",
                    LastName = $"Last{i}",
                    EnrollmentDate = DateTime.Today
                });
            }
            _context.SaveChanges();

            // Act — page 2
            var result = _controller.Index(null, null, null, 2) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.PageIndex);
            Assert.True(model.HasPreviousPage);
        }
    }

    public class DepartmentsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
