    public class NotificationsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_LimitsTo10Notifications()
        {
            // Arrange — drain queue and enqueue 15 notifications
            var service = new ContosoUniversity.Services.NotificationService();
            while (service.ReceiveNotification() != null) { }

            for (int i = 0; i < 15; i++)
            {
                service.SendNotification("Test", i.ToString(), $"Item {i}", EntityOperation.CREATE, "User");
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value!;
            var countProp = value.GetType().GetProperty("count");
            var count = (int)countProp!.GetValue(value)!;
            Assert.Equal(10, count); // Max limit is 10
        }
    }

    public class InstructorsControllerEdgeCaseTests : IDisposable
